package com.example.meetomxh;

import android.os.Bundle;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.example.meetomxh.models.Chat;
import com.example.meetomxh.repositories.ChatRepository;
import com.example.meetomxh.supabase.*;
import com.example.meetomxh.ui.AvatarViews;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.*;

/** Active members only; all role/removal mutations go through the authorized group RPC. */
public final class GroupMembersActivity extends AppCompatActivity {
    public static final String EXTRA_CHAT_ID="chat_id";
    private String chatId,self;private Chat chat;private LinearLayout rows;private TextView state;private Button invite;private boolean loading;
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);chatId=getIntent().getStringExtra(EXTRA_CHAT_ID);self=SessionManager.getInstance().uid();if(chatId==null){finish();return;}build();load();}
    private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(10),dp(16),dp(12));root.setBackgroundColor(getColor(R.color.app_bg));Button back=new Button(this);back.setText("‹  Thành viên nhóm");back.setAllCaps(false);back.setOnClickListener(v->finish());root.addView(back);state=new TextView(this);state.setTextColor(getColor(R.color.text_secondary));root.addView(state);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));invite=new Button(this);invite.setText("Thêm thành viên");invite.setAllCaps(false);invite.setOnClickListener(v->{if(chat!=null)ChatControls.invite(this,chat);});root.addView(invite);setContentView(root);}
    private void load(){if(loading)return;loading=true;state.setText("Đang tải thành viên…");Api.run(()->{Chat c=ChatRepository.getInstance().load(chatId);JSONArray members=(JSONArray)RpcClient.call("get_conversation_members",Api.obj("p_conversation_id",chatId));return new Object[]{c,members};},new Api.Callback<Object[]>(){public void success(Object[] result){loading=false;if(isFinishing())return;chat=(Chat)result[0];JSONArray members=(JSONArray)result[1];invite.setVisibility("admin".equals(chat.role)?View.VISIBLE:View.GONE);List<JSONObject> list=new ArrayList<>();for(int i=0;i<members.length();i++){JSONObject row=members.optJSONObject(i);if(row!=null)list.add(row);}list.sort(Comparator.comparingInt(GroupMembersActivity.this::rank).thenComparing(o->o.optString("display_name",""),String.CASE_INSENSITIVE_ORDER));rows.removeAllViews();for(JSONObject row:list)addMember(row);state.setText(list.isEmpty()?"Không có thành viên đang hoạt động.":list.size()+" thành viên đang hoạt động");}public void error(String e){loading=false;state.setText(e+" · Chạm để thử lại");state.setOnClickListener(v->load());}});}
    private int rank(JSONObject row){String id=row.optString("user_id");if(id.equals(chat.ownerId))return 0;if("admin".equals(row.optString("role")))return 1;return 2;}
    private void addMember(JSONObject member){LinearLayout row=new LinearLayout(this);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));ImageView avatar=new ImageView(this);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(avatar,new LinearLayout.LayoutParams(dp(48),dp(48)));AvatarViews.load(avatar,Dto.asset(Dto.nullable(member,"avatar_asset_id")),member.optString("avatar_preset","neutral"));LinearLayout labels=new LinearLayout(this);labels.setOrientation(1);labels.setPadding(dp(12),0,dp(8),0);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));String display=member.optString("display_name","").trim();if(display.isEmpty()||"null".equalsIgnoreCase(display))display="Người dùng";TextView name=new TextView(this);name.setText(display);name.setTextSize(16);name.setTextColor(getColor(R.color.text_primary));name.setMaxLines(3);labels.addView(name);TextView role=new TextView(this);String userId=member.optString("user_id");role.setText(userId.equals(chat.ownerId)?"Chủ nhóm":"admin".equals(member.optString("role"))?"Quản trị viên":"Thành viên");role.setTextSize(13);role.setTextColor(getColor(R.color.text_secondary));labels.addView(role);rows.addView(row,new LinearLayout.LayoutParams(-1,-2));row.setOnClickListener(v->memberActions(member));View divider=new View(this);divider.setBackgroundColor(getColor(R.color.divider_color));rows.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));}
    private void memberActions(JSONObject member){if(!"admin".equals(chat.role)||self.equals(member.optString("user_id"))||java.util.Objects.equals(chat.ownerId,member.optString("user_id")))return;String role=member.optString("role");String[] labels="admin".equals(role)?new String[]{"Loại khỏi nhóm","Hạ xuống thành viên"}:new String[]{"Loại khỏi nhóm","Đặt làm quản trị viên"};new android.app.AlertDialog.Builder(this).setItems(labels,(d,which)->{String action=which==0?"remove":"admin".equals(role)?"demote":"promote";new android.app.AlertDialog.Builder(this).setMessage("Xác nhận thay đổi quyền thành viên?").setNegativeButton("Hủy",null).setPositiveButton("Xác nhận",(x,w)->Api.run(()->RpcClient.call("manage_conversation_member",Api.obj("p_conversation_id",chatId,"p_target",member.optString("user_id"),"p_action",action)),new Api.Callback<Object>(){public void success(Object r){load();}public void error(String e){Toast.makeText(GroupMembersActivity.this,e,Toast.LENGTH_LONG).show();}})).show();}).show();}
    private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
}
